const tokyoFoods=[{"area": "아사쿠사·스미다", "name": "덴푸라·소바", "where": "아사쿠사", "kind": "향토·지역 대표", "description": "에도 음식 문화를 맛볼 수 있는 식사입니다. 튀김과 메밀면 중 취향에 맞춰 선택하세요.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/index.html"}, {"area": "아사쿠사·스미다", "name": "찬코나베", "where": "료고쿠 · 아사쿠사에서 이동 필요", "kind": "향토·지역 대표", "description": "고기와 채소를 함께 끓이는 스모 선수들의 전골입니다. 여럿이 식사할 때 좋습니다.", "source": "https://www.gotokyo.org/en/destinations/eastern-tokyo/ryogoku/index.html"}, {"area": "신주쿠", "name": "야키토리", "where": "오모이데 요코초", "kind": "지역 식사 선택지", "description": "닭고기를 꼬치에 구워 먹는 음식입니다. 작은 가게가 많으므로 좌석·차지·주문 조건을 확인하세요.", "source": "https://www.gotokyo.org/en/spot/63/index.html"}, {"area": "우에노·야나카", "name": "소바·덴푸라", "where": "우에노·야나카 일대", "kind": "도쿄 공통 메뉴", "description": "박물관 관람 사이에 고르기 좋은 식사입니다. 이 지역만의 향토음식은 아닙니다.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/index.html"}, {"area": "시부야·하라주쿠", "name": "하라주쿠 크레페", "where": "다케시타 거리", "kind": "지역 대표 간식", "description": "크림과 과일 등을 넣은 달콤한 크레페입니다. 쇼핑 중 간식으로 즐기기 좋습니다.", "source": "https://www.gotokyo.org/en/spot/48/index.html"}, {"area": "고쿄·분쿄", "name": "소바", "where": "분쿄 일대 · 간다도 별도 선택지", "kind": "도쿄 공통 메뉴", "description": "정원 산책 전후에 고르기 좋은 식사입니다. 전통 소바 가게를 찾는다면 간다 쪽도 고려하세요.", "source": "https://www.gotokyo.org/en/destinations/central-tokyo/kanda-and-jimbocho/"}, {"area": "도쿄타워·시바", "name": "스시·덴푸라", "where": "시바·하마마쓰초 일대", "kind": "도쿄 공통 메뉴", "description": "타워 관람 전후의 식사 선택지입니다. 가게별 가격대와 예약 여부를 확인하세요.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/index.html"}, {"area": "오다이바", "name": "몬자야키", "where": "쓰키시마 · 오다이바 밖, 별도 이동", "kind": "인근 향토음식", "description": "묽은 반죽을 철판에서 익혀 먹는 도쿄의 대표 음식입니다. 쓰키시마에서 먹는다면 별도 이동 일정을 잡으세요.", "source": "https://www.gotokyo.org/en/spot/85/index.html"}, {"area": "오다이바", "name": "라멘·돈부리", "where": "다이버시티 등 쇼핑시설", "kind": "지역 식사 선택지", "description": "시설 안에서 동선을 줄여 먹기 좋은 메뉴입니다. 오다이바 고유의 향토음식은 아닙니다.", "source": "https://www.gotokyo.org/en/spot/505/index.html"}, {"area": "기치조지·고엔지", "name": "멘치카츠", "where": "기치조지 역 북쪽 상점가", "kind": "지역 대표 간식", "description": "다진 고기를 튀긴 커틀릿입니다. 공원 산책 전후 간식으로 고르되 지정된 장소에서 드세요.", "source": "https://www.gotokyo.org/en/story/guide/japanese-comfort-food/index.html"}, {"area": "다치카와", "name": "도쿄 사야마차·차 디저트", "where": "다마 지역 특산 · 판매처 확인", "kind": "광역 특산품", "description": "도쿄 서부에서 생산되는 차입니다. 공원 방문과 함께 차나 관련 디저트를 찾아보세요.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/tokyo-local-food/index.html"}, {"area": "다카오", "name": "도로로 소바", "where": "다카오산 산기슭", "kind": "향토·지역 대표", "description": "갈아낸 마를 곁들인 메밀면입니다. 산행 전후에 먹기 좋은 다카오의 대표 메뉴입니다.", "source": "https://www.gotokyo.org/en/story/walks-and-tours/mt-takao/index.html"}, {"area": "오쿠타마", "name": "와사비를 곁들인 소바", "where": "오쿠타마", "kind": "지역 특산 활용", "description": "맑은 물에서 자라는 지역 와사비의 향을 즐기는 선택지입니다.", "source": "https://www.gourmet.gotokyo.org/article/109.html"}, {"area": "이즈 제도", "name": "오시마 우유·아시타바 간식", "where": "이즈 오시마 · 섬마다 다름", "kind": "섬 특산품", "description": "오시마 유제품이나 아시타바를 활용한 간식을 찾아보세요. 섬별 판매 품목이 다릅니다.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/tokyo-local-food/index.html"}, {"area": "오가사와라", "name": "열대과일·과일 디저트", "where": "지치지마 등 · 계절 확인", "kind": "섬 특산품", "description": "섬에서 나는 열대과일을 즐겨보세요. 수확 시기와 입고 여부에 따라 선택지가 달라집니다.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/tokyo-local-food/index.html"}, {"area": "간다·아키하바라", "name": "간다 소바", "where": "간다", "kind": "향토·지역 대표", "description": "오래된 소바 가게를 찾아 메밀 향과 쓰유를 맛보는 식사입니다.", "source": "https://www.gotokyo.org/en/destinations/central-tokyo/kanda-and-jimbocho/"}, {"area": "아카사카", "name": "스시·소바", "where": "아카사카 일대", "kind": "도쿄 공통 메뉴", "description": "신사 관람 뒤 식사 후보입니다. 특산품으로 단정하지 않고 취향과 예산에 맞춰 고르세요.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/index.html"}, {"area": "에도가와", "name": "소바·덴푸라", "where": "가사이역 등 · 공원과 이동 확인", "kind": "도쿄 공통 메뉴", "description": "공원 산책 후 식사 후보입니다. 공원 내부와 역 주변 식당의 위치를 구분해 확인하세요.", "source": "https://www.gotokyo.org/en/see-and-do/drinking-and-dining/index.html"}];
const expansionJapanese={"일본과학미래관":"日本科学未来館","지구와 우주, 로봇과 미래 기술을 전시로 만나는 과학관입니다.":"地球や宇宙、ロボット、未来の技術を展示で学ぶ科学館です。","관심 전시를 골라 관람하세요. 특별전과 돔 시어터는 별도 예약·요금을 확인하세요.":"興味のある展示を選び、特別展やドームシアターの予約・料金を確認しましょう。","도쿄 빅사이트":"東京ビッグサイト","아리아케에 있는 국제전시장으로 코미케 등 대형 행사가 열리는 곳입니다.":"有明にある国際展示場。コミックマーケットなどの大型イベントが開かれます。","상설 관광 전시관이 아닙니다. 행사 날짜와 입장권을 먼저 확인하고 방문하세요.":"常設の観光展示館ではありません。イベント日程と入場券を先に確認してください。","다이버시티 도쿄 플라자":"ダイバーシティ東京 プラザ","쇼핑과 식사를 함께 즐길 수 있는 오다이바의 대표 복합시설입니다.":"買い物と食事を楽しめるお台場の代表的な複合施設です。","건담 입상과 주변 광장을 둘러보고 실내 쇼핑을 연결해보세요.":"ガンダム立像と広場を見た後、館内の買い物も楽しめます。","도쿄 조이폴리스":"東京ジョイポリス","덱스 도쿄 비치 안에 있는 실내 놀이시설입니다.":"デックス東京ビーチ内の屋内型テーマパークです。","비 오는 날 대안으로 좋습니다. 놀이기구별 이용 조건과 티켓 종류를 확인하세요.":"雨の日にも便利。アトラクションの利用条件とチケットの種類を確認しましょう。","신주쿠 골든가이":"新宿ゴールデン街","작은 가게가 밀집한 좁은 골목에서 신주쿠의 밤 문화를 만납니다.":"小さな店が並ぶ路地で新宿の夜の文化に触れられます。","저녁에 방문하되 촬영 규칙과 가게별 차지·영업시간을 확인하세요.":"夜の訪問向き。撮影ルールや各店のチャージ・営業時間を確認してください。","오모이데 요코초":"思い出横丁","신주쿠역 서쪽의 작은 식당 골목입니다.":"新宿駅西側にある小さな飲食店街です。","야키토리 등 간단한 식사를 골라보세요. 좁은 가게의 주문 규칙을 확인하세요.":"焼き鳥などを楽しみ、各店の注文ルールも確認しましょう。","국립과학박물관":"国立科学博物館","자연사와 과학을 폭넓게 다루는 우에노의 대표 박물관입니다.":"自然史と科学を幅広く扱う上野の代表的な博物館です。","공룡·생물 전시 등 관심 분야를 정해 둘러보면 좋습니다.":"恐竜や生き物など、興味のあるテーマを決めて巡りましょう。","네즈 미술관":"根津美術館","동아시아 고미술과 건축, 정원을 함께 감상하는 미술관입니다.":"東アジアの古美術、建築、庭園を楽しむ美術館です。","오모테산도 산책에 연결하세요. 우에노 쪽 네즈 신사와는 다른 장소입니다.":"表参道散策と組み合わせて。上野方面の根津神社とは別の場所です。","다케시타 거리":"竹下通り","패션과 달콤한 간식으로 알려진 하라주쿠의 보행자 거리입니다.":"ファッションとスイーツで知られる原宿の歩行者通りです。","메이지 신궁 관람 전후에 쇼핑과 크레페를 즐겨보세요.":"明治神宮の参拝前後に買い物やクレープを楽しめます。","조조지":"増上寺","도쿠가와 가문과 인연이 깊고 도쿄타워와 함께 보기 좋은 사찰입니다.":"徳川家ゆかりの寺院。東京タワーと合わせて訪ねられます。","경내와 시바공원을 산책하고 뒤편 도쿄타워 풍경도 담아보세요.":"境内と芝公園を歩き、東京タワーを背景にした景色も楽しめます。","미타카의 숲 지브리 미술관":"三鷹の森ジブリ美術館","지브리 애니메이션의 세계와 제작 과정을 만나는 미술관입니다.":"ジブリアニメーションの世界と制作に触れる美術館です。","사전 예약이 필수입니다. 예약이 있을 때 이노카시라 공원과 묶으세요.":"事前予約が必要です。予約を取ってから井の頭公園と組み合わせましょう。","닛파라 종유동":"日原鍾乳洞","석회암이 만든 지하 풍경을 탐방하는 오쿠타마의 동굴입니다.":"石灰岩が作った地下の景観を探訪する奥多摩の洞窟です。","오쿠타마호와는 별도 이동입니다. 버스와 귀가편, 미끄럽지 않은 신발을 준비하세요.":"奥多摩湖からは別途移動が必要です。バスの往復便と滑りにくい靴を準備しましょう。","하부항":"波浮港","이즈 오시마 남쪽의 항구와 오래된 마을 풍경을 즐기는 곳입니다.":"伊豆大島南部の港と古い街並みを楽しむ場所です。","미하라산과 같은 섬이지만 거리가 있습니다. 섬 내 교통에 맞춰 묶으세요.":"三原山と同じ島ですが離れています。島内交通に合わせて計画しましょう。","고미나토 해변":"小港海岸","지치지마 남부의 바다와 모래사장을 만나는 해변입니다.":"父島南部の海と砂浜を楽しめる海岸です。","섬 체류 일정에 넣고 귀가 교통과 바다 상태를 확인하세요.":"島での滞在日程に組み込み、帰りの交通と海況を確認してください。","다카오산 야쿠오인":"高尾山薬王院","다카오산 산길에서 만나는 산악 신앙의 사찰입니다.":"高尾山の山道にある山岳信仰の寺院です。","다카오산 일정 안의 선택지입니다. 산 전체 관람시간과 중복해 계산하지 마세요.":"高尾山巡りの途中の選択肢です。山全体の所要時間と重複して計上しないようにしましょう。","간다묘진":"神田明神","에도의 역사와 아키하바라 문화를 함께 느낄 수 있는 신사입니다.":"江戸の歴史と秋葉原の文化に触れられる神社です。","아키하바라 구경과 연결해 경내를 둘러보세요.":"秋葉原散策と組み合わせて境内を巡りましょう。","히에 신사":"日枝神社","산노마쓰리로 알려진 도심의 신사입니다.":"山王祭で知られる都心の神社です。","도리이 계단과 경내를 둘러보고 아카사카에서 식사하세요.":"鳥居の階段と境内を巡り、赤坂で食事を楽しめます。","가사이 임해공원":"葛西臨海公園","도쿄만을 바라보며 산책과 자연 관찰을 즐기는 넓은 공원입니다.":"東京湾を眺めながら散策や自然観察を楽しむ広い公園です。","에도가와 불꽃놀이 행사장과는 다른 위치입니다. 해변 산책 일정으로 계획하세요.":"江戸川花火大会の会場とは別の場所です。海辺の散策として計画してください。","도쿄 돔 시티":"東京ドームシティ","놀이시설과 식당을 함께 즐기는 도심 복합공간입니다.":"アトラクションや飲食店が集まる都心の複合施設です。","고라쿠엔 정원과 연결하되 경기·공연이 있는 날의 혼잡을 확인하세요.":"小石川後楽園と合わせて。試合・公演開催日の混雑を確認しましょう。","덴푸라·소바":"天ぷら・そば","아사쿠사":"浅草","향토·지역 대표":"郷土・地域の定番","에도 음식 문화를 맛볼 수 있는 식사입니다. 튀김과 메밀면 중 취향에 맞춰 선택하세요.":"江戸の食文化を味わえる食事です。天ぷらとそばから好みに合わせて選んでください。","찬코나베":"ちゃんこ鍋","료고쿠 · 아사쿠사에서 이동 필요":"両国・浅草から移動が必要","고기와 채소를 함께 끓이는 스모 선수들의 전골입니다. 여럿이 식사할 때 좋습니다.":"肉と野菜を一緒に煮込む、力士ゆかりの鍋料理です。複数人での食事にも向いています。","야키토리":"焼き鳥","지역 식사 선택지":"地域の食事候補","닭고기를 꼬치에 구워 먹는 음식입니다. 작은 가게가 많으므로 좌석·차지·주문 조건을 확인하세요.":"鶏肉を串に刺して焼く料理です。小さな店が多いため、席料やチャージ、注文条件を確認してください。","소바·덴푸라":"そば・天ぷら","우에노·야나카 일대":"上野・谷中周辺","도쿄 공통 메뉴":"東京の定番料理","박물관 관람 사이에 고르기 좋은 식사입니다. 이 지역만의 향토음식은 아닙니다.":"博物館巡りの合間の食事候補。この地域だけの郷土料理ではありません。","하라주쿠 크레페":"原宿クレープ","지역 대표 간식":"地域の定番グルメ","크림과 과일 등을 넣은 달콤한 크레페입니다. 쇼핑 중 간식으로 즐기기 좋습니다.":"クリームや果物などを包む甘いクレープです。買い物の途中のおやつに向いています。","소바":"そば","분쿄 일대 · 간다도 별도 선택지":"文京周辺・神田も別の候補","정원 산책 전후에 고르기 좋은 식사입니다. 전통 소바 가게를 찾는다면 간다 쪽도 고려하세요.":"庭園散策の前後に選びやすい食事です。老舗のそば店を探すなら神田方面も検討してください。","스시·덴푸라":"寿司・天ぷら","시바·하마마쓰초 일대":"芝・浜松町周辺","타워 관람 전후의 식사 선택지입니다. 가게별 가격대와 예약 여부를 확인하세요.":"タワー観覧前後の食事候補。店舗ごとの予算と予約を確認してください。","몬자야키":"もんじゃ焼き","쓰키시마 · 오다이바 밖, 별도 이동":"月島・お台場の外、別途移動","인근 향토음식":"近隣の郷土料理","묽은 반죽을 철판에서 익혀 먹는 도쿄의 대표 음식입니다. 쓰키시마에서 먹는다면 별도 이동 일정을 잡으세요.":"ゆるい生地を鉄板で焼いて食べる東京の代表的な料理です。月島で食べる場合は別途移動時間を確保してください。","라멘·돈부리":"ラーメン・丼","다이버시티 등 쇼핑시설":"ダイバーシティなどの商業施設","시설 안에서 동선을 줄여 먹기 좋은 메뉴입니다. 오다이바 고유의 향토음식은 아닙니다.":"施設内で移動を抑えたい時の候補。お台場固有の郷土料理ではありません。","멘치카츠":"メンチカツ","기치조지 역 북쪽 상점가":"吉祥寺駅北側の商店街","다진 고기를 튀긴 커틀릿입니다. 공원 산책 전후 간식으로 고르되 지정된 장소에서 드세요.":"ひき肉を揚げたカツです。公園散策の前後のおやつに選び、指定された場所で食べてください。","도쿄 사야마차·차 디저트":"東京狭山茶・お茶のスイーツ","다마 지역 특산 · 판매처 확인":"多摩地域の特産・販売店を確認","광역 특산품":"広域の特産品","도쿄 서부에서 생산되는 차입니다. 공원 방문과 함께 차나 관련 디저트를 찾아보세요.":"東京西部で生産されるお茶です。公園訪問と合わせて、お茶や関連スイーツを探してみてください。","도로로 소바":"とろろそば","다카오산 산기슭":"高尾山の麓","갈아낸 마를 곁들인 메밀면입니다. 산행 전후에 먹기 좋은 다카오의 대표 메뉴입니다.":"すりおろした山芋を添えるそばです。登山の前後に食べやすい高尾の定番メニューです。","와사비를 곁들인 소바":"わさびを添えたそば","오쿠타마":"奥多摩","지역 특산 활용":"地域の食材を楽しむ","맑은 물에서 자라는 지역 와사비의 향을 즐기는 선택지입니다.":"清流で育つ地域のわさびの香りを楽しむ選択肢です。","오시마 우유·아시타바 간식":"大島の牛乳・明日葉のおやつ","이즈 오시마 · 섬마다 다름":"伊豆大島・島ごとに異なります","섬 특산품":"島の特産品","오시마 유제품이나 아시타바를 활용한 간식을 찾아보세요. 섬별 판매 품목이 다릅니다.":"大島の乳製品や明日葉を使ったおやつを探してみて。品ぞろえは島ごとに異なります。","열대과일·과일 디저트":"トロピカルフルーツ・スイーツ","지치지마 등 · 계절 확인":"父島など・旬を確認","섬에서 나는 열대과일을 즐겨보세요. 수확 시기와 입고 여부에 따라 선택지가 달라집니다.":"島のトロピカルフルーツを楽しめます。収穫時期や入荷状況で品ぞろえが変わります。","간다 소바":"神田のそば","간다":"神田","오래된 소바 가게를 찾아 메밀 향과 쓰유를 맛보는 식사입니다.":"老舗そば店で、そばの香りとつゆを味わう食事です。","스시·소바":"寿司・そば","아카사카 일대":"赤坂周辺","신사 관람 뒤 식사 후보입니다. 특산품으로 단정하지 않고 취향과 예산에 맞춰 고르세요.":"参拝後の食事候補。地域限定の名物ではなく、好みと予算で選びましょう。","가사이역 등 · 공원과 이동 확인":"葛西駅など・公園からの移動を確認","공원 산책 후 식사 후보입니다. 공원 내부와 역 주변 식당의 위치를 구분해 확인하세요.":"公園散策後の食事候補。園内と駅周辺の飲食店は場所を分けて確認してください。","추천 음식":"おすすめの食べ物","이 지역에서 무엇을 먹을까요?":"このエリアで何を食べる？","향토음식과 일반 식사 선택지를 구분했습니다. 표시된 위치가 권역 밖이면 별도 이동이 필요합니다.":"郷土料理と一般的な食事候補を分けています。エリア外の場所は別途移動が必要です。","음식·지역 안내 ↗":"料理・地域の案内 ↗","관심 전시·활동에 맞춰 조정":"興味のある展示・体験に合わせて調整","공식 관광 안내에 연결된 장소입니다. 지도 버튼으로 해당 시설을 확인하세요.":"公式観光案内に掲載された場所です。地図ボタンで施設を確認できます。","이 권역의 추천 음식":"このエリアのおすすめ料理","코미케 공식 일정·참가 안내 ↗":"コミックマーケット公式日程・参加案内 ↗","공식 자료 확인: 2026.09.23":"公式情報確認：2026.09.23"};
function renderFoods(){const host=document.querySelector('#foodPanel');if(!host)return;const active=state.view==='explore'&&contentTab==='foods';host.hidden=!active;const tab=document.querySelector('#foodsTab');tab.hidden=!completePrefs.includes(state.pref);tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active));if(!active)return;
 host.innerHTML='<h2>이 지역에서 무엇을 먹을까요?</h2><p>향토음식과 일반 식사 선택지를 구분했습니다. 표시된 위치가 권역 밖이면 별도 이동이 필요합니다.</p><div class="foodGrid"></div>';
 const entries=foodsForPref(state.pref).filter(f=>state.area==='전체'||f.area===state.area||f.area.endsWith('전역'));
 for(const f of entries){const card=document.createElement('article');card.className='foodCard';card.dataset.foodName=f.name;card.dataset.foodArea=f.area;card.dataset.foodKind=f.kind;card.innerHTML=`<small>${f.area} · ${f.kind}</small><h3>${f.name}</h3><p class="foodLocation">${f.where}</p><p>${f.description}</p><a href="${f.source}" target="_blank" rel="noopener">음식·지역 안내 ↗</a>`;host.querySelector('.foodGrid').append(card)}
 if(typeof localize==='function')localize();
}
